/*Table structure for table `user_conversation_list` */

DROP TABLE IF EXISTS `user_conversation_list`;

CREATE TABLE `user_conversation_list` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` bigint(20) unsigned NOT NULL COMMENT '用户ID',
  `conversation_id` varchar(64) NOT NULL COMMENT '会话ID',
  `last_read_seq` bigint(20) unsigned DEFAULT '0' COMMENT '此会话用户已读的最后一条消息',
  `notify_type` int(11) DEFAULT '0' COMMENT '会话收到消息的提醒类型，0未屏蔽，正常提醒 1屏蔽 2强提醒',
  `is_top` tinyint(2) DEFAULT '0' COMMENT '会话是否被置顶展示 0否 1是',
  `version` int(11) DEFAULT '1' COMMENT '会话版本号',
  `is_del` tinyint(2) DEFAULT '1' COMMENT '是否删除 1-否 2-是',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_conversation_idx` (`user_id`,`conversation_id`),
  KEY `conversation_user_idx` (`conversation_id`,`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='用户会话链';

/*Data for the table `user_conversation_list` */

insert  into `user_conversation_list`(`id`,`user_id`,`conversation_id`,`last_read_seq`,`notify_type`,`is_top`,`version`,`is_del`,`created_at`,`updated_at`) values (1,567405681192206837,'567405681192206837-567405764642079221',0,0,0,1,1,'2025-05-21 11:10:06','2025-05-21 11:10:06'),(2,567405764642079221,'567405681192206837-567405764642079221',3,0,0,1,1,'2025-05-21 11:10:06','2025-05-22 10:10:59');

/*Table structure for table `user_info` */

DROP TABLE IF EXISTS `user_info`;

CREATE TABLE `user_info` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL COMMENT '用户id',
  `nick_name` varchar(100) DEFAULT NULL COMMENT '昵称',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像',
  `gender` tinyint(2) DEFAULT '3' COMMENT '性别 1男 2女 3未知',
  `birth_day` varchar(50) DEFAULT NULL COMMENT '生日',
  `self_signature` varchar(255) DEFAULT NULL COMMENT '个性签名',
  `friend_allow_type` int(10) NOT NULL DEFAULT '1' COMMENT '加好友验证类型（Friend_AllowType） 1无需验证 2需要验证',
  `silent_flag` int(10) NOT NULL DEFAULT '0' COMMENT '禁言标识 1禁言',
  `status` int(20) NOT NULL DEFAULT '1' COMMENT '用户状态  0:异常  1:正常',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user` (`user_id`),
  KEY `user_phone_email_pass` (`user_id`,`nick_name`,`avatar`,`gender`),
  KEY `deleted_idx` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='用户信息表';

